-- Expand the free practice bank to the 110-question SKD practice composition.
-- All inserted items are original practice questions, not official BKN exam questions.
ALTER TABLE public.questions
  ADD COLUMN IF NOT EXISTS option_scores jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.questions
  DROP CONSTRAINT IF EXISTS questions_option_scores_object_check;
ALTER TABLE public.questions
  ADD CONSTRAINT questions_option_scores_object_check
  CHECK (jsonb_typeof(option_scores) = 'object');

-- Existing TKP questions: best response gets 5, remaining options get 4..1.
UPDATE public.questions q
SET option_scores = (
  SELECT jsonb_object_agg(letter, 6 - rank_no)
  FROM (
    SELECT letter, row_number() OVER (ORDER BY (letter = q.correct_answer) DESC, ord) AS rank_no
    FROM unnest(ARRAY['A','B','C','D','E']) WITH ORDINALITY AS x(letter, ord)
  ) ranked
)
WHERE q.category = 'TKP' AND q.option_scores = '{}'::jsonb;

