yat (3)","Pasal 34 ayat (1)"],"category":"TWK","question":"Persamaan kedudukan warga negara di dalam hukum dan pemerintahan diatur dalam...","explanation":"Pasal 27 ayat (1) mengatur persamaan kedudukan warga negara.","option_scores":{},"correct_answer":"A"},{"topic":"Wawasan kebangsaan","options":["Memperluas wilayah negara lain","Mencerdaskan kehidupan bangsa","Menguasai perdagangan dunia","Membatasi pendidikan","Menghapus budaya"],"category":"TWK","question":"Salah satu tujuan negara yang tercantum dalam Pembukaan UUD 1945 adalah...","explanation":"Mencerdaskan kehidupan bangsa merupakan salah satu tujuan nasional.","option_scores":{},"correct_answer":"B"},{"topic":"Wawasan kebangsaan","options":["Batang tubuh Pasal 1","Pembukaan UUD 1945 alinea keempat","Peraturan daerah","Sumpah jabatan","Keputusan partai"],"category":"TWK","question":"Tujuan nasional Indonesia tercantum dalam...","explanation":"Alinea keempat Pembukaan UUD memuat tujuan pembentukan pemerintah negara.","option_scores":{},"correct_answer":"B"}]'::jsonb)
    AS x(category text, topic text, question text, options jsonb,
         correct_answer text, explanation text, option_scores jsonb)
)
INSERT INTO public.questions
  (category, topic, question, options, correct_answer, explanation,
   option_scores, is_published, is_premium)
SELECT i.category, i.topic, i.question, i.options, i.correct_answer,
       i.explanation, i.option_scores, true, false
FROM incoming i
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions q WHERE q.question = i.question
);

CREATE OR REPLACE FUNCTION public.submit_exam_attempt(
  p_title text, p_category text, p_answers jsonb, p_duration_seconds integer
)
RETURNS TABLE(attempt_id uuid, total_questions integer, correct_answers integer, score integer)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_total integer;
  v_correct integer;
  v_score integer;
  v_attempt_id uuid;
  v_answers jsonb;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_title IS NULL OR length(trim(p_title)) = 0 OR length(p_title) > 120 THEN RAISE EXCEPTION 'Invalid exam title'; END IF;
  IF p_category IS NULL OR length(trim(p_category)) = 0 OR length(trim(p_category)) > 40 THEN RAISE EXCEPTION 'Invalid exam category'; END IF;
  IF p_answers IS NULL OR jsonb_typeof(p_answers) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_answers) < 1 OR jsonb_array_length(p_answers) > 110 THEN
    RAISE EXCEPTION 'Invalid answer list';
  END IF;
  IF p_duration_seconds IS NULL OR p_duration_seconds < 0 OR p_duration_seconds > 6600 THEN
    RAISE EXCEPTION 'Invalid exam duration';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_answers) item(value)
    WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'object'
       OR jsonb_typeof(item.value->'question_id') IS DISTINCT FROM 'string'
       OR (item.value ? 'answer') IS NOT TRUE
       OR (jsonb_typeof(item.value->'answer') IS DISTINCT FROM 'null'
           AND jsonb_typeof(item.value->'answer') IS DISTINCT FROM 'string')
       OR ((item.value->>'answer') IS NOT NULL
           AND (item.value->>'answer') NOT IN ('A','B','C','D','E'))
       OR jsonb_typeof(item.value->'is_marked') IS DISTINCT FROM 'boolean'
  ) THEN RAISE EXCEPTION 'Invalid answer format'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(p_answers) a(question_id uuid, answer text, is_marked boolean)
    WHERE a.question_id IS NULL
  ) THEN RAISE EXCEPTION 'Invalid question ID'; END IF;
  IF (
    SELECT count(*) <> count(DISTINCT a.question_id)
    FROM jsonb_to_recordset(p_answers) a(question_id uuid, answer text, is_marked boolean)
  ) THEN RAISE EXCEPTION 'Duplicate question IDs'; END IF;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE a.answer = q.correct_answer)::integer,
         coalesce(sum(
           CASE
             WHEN a.answer IS NULL THEN 0
             WHEN q.category = 'TKP' THEN coalesce((q.option_scores->>a.answer)::integer, 1)
             WHEN a.answer = q.correct_answer THEN 5
             ELSE 0
           END
         ), 0)::integer
    INTO v_total, v_correct, v_score
  FROM jsonb_to_recordset(p_answers) a(question_id uuid, answer text, is_marked boolean)
  JOIN public.questions q
    ON q.id = a.question_id AND q.is_published = true AND q.is_premium = false;

  IF v_total <> jsonb_array_length(p_answers) THEN RAISE EXCEPTION 'One or more questions are unavailable'; END IF;
  IF v_correct < 0 OR v_correct > v_total OR v_score < 0 OR v_score > 550 THEN
    RAISE EXCEPTION 'Calculated result is out of range';
  END IF;
  SELECT coalesce(jsonb_object_agg(a.question_id::text, a.answer), '{}'::jsonb)
    INTO v_answers
  FROM jsonb_to_recordset(p_answers) a(question_id uuid, answer text, is_marked boolean);

  INSERT INTO public.exam_attempts
    (user_id, title, category, total_questions, correct_answers, score, duration_seconds, answers)
  VALUES
    (v_user_id, trim(p_title), trim(p_category), v_total, v_correct, v_score, p_duration_seconds, v_answers)
  RETURNING id INTO v_attempt_id;

  RETURN QUERY SELECT v_attempt_id, v_total, v_correct, v_score;
END;
$function$;

REVOKE ALL ON FUNCTION public.submit_exam_attempt(text,text,jsonb,integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.submit_exam_attempt(text,text,jsonb,integer) TO authenticated;

DROP FUNCTION IF EXISTS public.get_exam_review(uuid);
CREATE FUNCTION public.get_exam_review(p_attempt_id uuid)
RETURNS TABLE(
  question_id uuid, category text, topic text, question text, options jsonb,
  selected_answer text, correct_answer text, explanation text, selected_score integer
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_answers jsonb;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT ea.answers INTO v_answers
  FROM public.exam_attempts ea
  WHERE ea.id = p_attempt_id AND ea.user_id = v_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Exam attempt not found'; END IF;

  RETURN QUERY
  SELECT q.id, q.category, q.topic, q.question, q.options,
         v_answers->>q.id::text, q.correct_answer, q.explanation,
         CASE
           WHEN q.category = 'TKP' THEN coalesce((q.option_scores->>(v_answers->>q.id::text))::integer, 0)
           WHEN (v_answers->>q.id::text) = q.correct_answer THEN 5
           ELSE 0
         END
  FROM public.questions q
  WHERE q.id IN (SELECT key::uuid FROM jsonb_each(v_answers))
  ORDER BY q.category, q.created_at, q.id;
END;
$function$;
REVOKE ALL ON FUNCTION public.get_exam_review(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_exam_review(uuid) TO authenticated;
